std::wstring modelState(const json& row){static const std::map<std::string,std::wstring> labels={{"requested",L"승인 대기"},{"approved",L"승인됨"},{"rejected",L"거절됨"},{"downloading",L"다운로드 중"},{"verifying",L"파일 검사 중"},{"paused",L"일시정지"},{"failed",L"실패"},{"verified",L"파일 확인 완료"},{"active",L"등록됨"},{"cancelled",L"요청 취소됨"}};auto found=labels.find(str(row,"state"));return found==labels.end()?L"상태 확인 필요":found->second;}
