void modelsReply(const Event& event){auto& data=event.data;if(str(data,"scope")!=store->workspaceScope||str(data,"owner")!=str(accountProfile,"account_id")||data.value("serial",uint64_t(0))!=modelSerial)return;if(str(data,"action")=="local_progress"){auto total=data.value("total",uint64_t(0)),done=data.value("received",uint64_t(0));modelMessage=wide(str(data,"stage"))+L" · "+std::to_wstring(done/1024/1024)+L" / "+std::to_wstring(total/1024/1024)+L" MB";InvalidateRect(hwnd,nullptr,FALSE);return;}modelLocalUploading=false;modelBusy=false;modelNextPoll=GetTickCount64()+2000;if(flag(data,"failed")){modelPollFailed=true;modelMessage=wide(str(data,"message","요청 실패 · 서버 권한과 명세를 확인한 뒤 새로고침하세요"));return;}modelPollFailed=false;auto body=data.at("reply");auto action=str(data,"action");if(action=="list"){modelRows=body["requests"];modelLoaded=true;modelMessage=L"";}else if(action=="inspect"){modelsSync();auto sent=data.at("sent");for(auto key:{"repo","revision","file"})if(str(modelForm,key)!=str(sent,key)){modelMessage=L"입력이 바뀌었습니다 · 출처를 다시 확인하세요";return;}auto revision=str(body,"revision"),sha=str(body,"sha256");if(revision.size()!=40||sha.size()!=64||revision.find_first_not_of("0123456789abcdef")!=std::string::npos||sha.find_first_not_of("0123456789abcdef")!=std::string::npos){modelMessage=L"출처의 고정 버전과 해시를 확인하지 못했습니다";return;}for(auto key:{"revision","sha256","bytes"})modelForm[key]=str(body,key);if(str(modelForm,"license_url").empty())modelForm["license_url"]="https://huggingface.co/"+str(modelForm,"repo")+"/blob/"+revision+"/LICENSE";applyModelInputs();modelsSync();modelMessage=L"출처의 버전·해시·용량을 가져왔습니다";}else{if(action=="create"){modelFormOpen=false;clearModelControls();if(page==14)rebuild(false);}modelSelected=str(body,"id",modelSelected);modelLoaded=false;modelNextPoll=0;modelMessage=action=="activate"?L"등록 완료 · 고급 설정에서 서버 모델 목록을 갱신하세요":action=="local_upload"?L"내 파일 검사 완료 · 활성화를 선택하면 모델 목록에 등록됩니다.":L"요청 처리 완료";}InvalidateRect(hwnd,nullptr,FALSE);}
